1	<!doctype html>
2	<html lang="en">
3	<head>
4	<meta charset="utf-8">
5	<meta name="viewport" content="width=device-width, initial-scale=1">
6	<meta name="color-scheme" content="light dark">
7	<title>Quiz score — design mockup</title>
8	<!-- Stage 4 design file only (ux-ui-designer). Static HTML + CSS: no scripts, no external assets, no app logic.
9	     Generated from the token names in docs/process/ui-design.md; message texts copied from the catalogue in docs/user-stories.md.
10	     data-m attributes mark catalogue texts for the copy check; they are not part of the app. -->
11	<style>
12	/* ===== Design tokens (names as in ui-design.md). Light = default; dark = prefers-color-scheme in the app.
13	   In this mockup each .theme container sets its own values so both themes are visible at once. ===== */
14	.theme {
15	  --font-sans: system-ui, -apple-system, "Segoe UI", Roboto, "Helvetica Neue", Arial, sans-serif;
16	  --text-xs: 12px; --text-sm: 13px; --text-base: 15px; --text-md: 17px; --text-lg: 20px; --text-verdict: 40px; --text-score: 64px;
17	  --weight-light: 300; --weight-regular: 400; --weight-medium: 500; --weight-semibold: 600;
18	  --leading-none: 1; --leading-heading: 1.25; --leading-tight: 1.4; --leading-normal: 1.5;
19	  --tracking-eyebrow: 0.12em; --tracking-score: -0.03em; --tracking-verdict: -0.01em;
20	  --space-1: 4px; --space-2: 8px; --space-3: 12px; --space-4: 16px; --space-5: 20px; --space-6: 24px; --space-8: 32px; --space-10: 40px; --space-12: 48px;
21	  --radius-sm: 4px; --radius-md: 6px;
22	  --control-h: 44px; --border-w: 1px; --focus-w: 2px; --focus-offset: 2px;
23	  --icon-sm: 16px; --icon-verdict: 40px;
24	  --card-max: 520px; --input-max-wide: 240px; --space-field-gap: var(--space-3); --error-slot-h: calc(2 * var(--text-sm) * var(--leading-tight));
25	  --result-min-h: 196px;
26	  --duration-fast: 150ms; --duration-base: 200ms; --ease-out: cubic-bezier(0.2, 0, 0, 1);
27	}
28	.theme--light { color-scheme: light;
29	  --color-bg: #F5F3EE; --color-surface: #FFFFFF; --color-text: #1B1F24; --color-muted: #5A6069;
30	  --color-accent: #1F4E79; --color-accent-tint: #E9EFF6; --color-border: #DDD8CD; --color-field-border: #8A9099; --color-field-border-hover: #5A6069;
31	  --color-focus: #1F4E79; --color-pass: #1D6B3A; --color-pass-tint: #E6F2E9; --color-fail: #A8322D; --color-fail-tint: #FBE9E7; --color-error: #A8322D;
32	  --shadow-card: 0 1px 2px rgba(27,31,36,.06), 0 8px 24px rgba(27,31,36,.06); }
33	.theme--dark { color-scheme: dark;
34	  --color-bg: #111316; --color-surface: #1B1E23; --color-text: #ECEAE4; --color-muted: #A4A9B1;
35	  --color-accent: #8EB9E8; --color-accent-tint: #22303F; --color-border: #353A42; --color-field-border: #6E747E; --color-field-border-hover: #A4A9B1;
36	  --color-focus: #8EB9E8; --color-pass: #6FCF97; --color-pass-tint: #16301F; --color-fail: #F2958D; --color-fail-tint: #3A1E1C; --color-error: #F2958D;
37	  --shadow-card: 0 1px 2px rgba(0,0,0,.4), 0 8px 24px rgba(0,0,0,.3); }
38	
39	/* ===== Mockup page chrome (not part of the app) ===== */
40	* { box-sizing: border-box; }
41	body { margin: 0; background: #E4E5E8; color: #1A1D21; font-family: system-ui, -apple-system, "Segoe UI", Roboto, "Helvetica Neue", Arial, sans-serif; line-height: 1.5; }
42	.page { max-width: 1280px; margin: 0 auto; padding: 32px 16px 56px; }
43	.page-head { max-width: 80ch; margin-bottom: 24px; }
44	.page-head .kicker { margin: 0; font-size: 13px; font-weight: 600; letter-spacing: .08em; text-transform: uppercase; color: #4A5058; }
45	.page-head h1 { margin: 4px 0 8px; font-size: 28px; line-height: 1.2; }
46	.page-head p { margin: 0 0 6px; font-size: 15px; }
47	.part { margin-top: 40px; }
48	.part-title { margin: 0 0 4px; font-size: 22px; border-top: 2px solid #1A1D21; padding-top: 12px; }
49	.part-note { margin: 0 0 16px; font-size: 14px; color: #4A5058; }
50	.state { margin-top: 28px; }
51	.state-title, .strip-title { margin: 0; font-size: 17px; }
52	.state-letter { color: #4A5058; font-variant-numeric: tabular-nums; }
53	.state-note { margin: 2px 0 10px; font-size: 14px; color: #4A5058; }
54	.pair { display: grid; grid-template-columns: minmax(0, 1fr); gap: 16px; }
55	@media (min-width: 1000px) { .pair { grid-template-columns: repeat(2, minmax(0, 1fr)); } }
56	.theme-label { margin: 0 0 4px; font-size: 12px; font-weight: 700; letter-spacing: .06em; text-transform: uppercase; color: #4A5058; }
57	.viewport { container: app / inline-size; background: var(--color-bg); border: 1px solid #C9CBD0; border-radius: 10px; overflow: hidden; }
58	.strip-title { margin-top: 24px; }
59	.devices { display: flex; flex-wrap: wrap; gap: 24px; margin-top: 10px; }
60	.device-fig { margin: 0; width: 375px; max-width: 100%; }
61	.device-cap { font-size: 13px; font-weight: 600; margin-bottom: 4px; }
62	.device { width: 100%; }
63	
64	/* ===== App styles: components use tokens only ===== */
65	.app { padding: var(--space-6) var(--space-4) var(--space-8); font-family: var(--font-sans); color: var(--color-text); }
66	@container app (min-width: 600px) { .app { padding: var(--space-12) var(--space-10); } }
67	.sr-only { position: absolute; width: 1px; height: 1px; padding: 0; margin: -1px; overflow: hidden; clip: rect(0 0 0 0); white-space: nowrap; border: 0; }
68	.card { max-width: var(--card-max); margin: 0 auto; background: var(--color-surface); border: var(--border-w) solid var(--color-border); border-radius: var(--radius-md); box-shadow: var(--shadow-card); padding: var(--space-6) var(--space-5) var(--space-6); }
69	@container app (min-width: 600px) { .card { padding: var(--space-8) var(--space-10) var(--space-10); } }
70	.eyebrow { margin: 0; font-size: var(--text-xs); line-height: var(--leading-tight); font-weight: var(--weight-semibold); letter-spacing: var(--tracking-eyebrow); text-transform: uppercase; color: var(--color-muted); }
71	.title { margin: var(--space-1) 0 0; font-size: var(--text-lg); line-height: var(--leading-heading); font-weight: var(--weight-semibold); }
72	.sub { margin: var(--space-1) 0 var(--space-6); font-size: var(--text-sm); line-height: var(--leading-tight); color: var(--color-muted); }
73	
74	/* fields: one column at every width; on wide windows inputs keep a ledger-like width and errors fit on one line */
75	.fields { display: grid; grid-template-columns: minmax(0, 1fr); }
76	@container app (min-width: 600px) {
77	  .fields { --error-slot-h: calc(var(--text-sm) * var(--leading-tight)); --space-field-gap: var(--space-4); }
78	  .input, .input-wrap { max-width: var(--input-max-wide); }
79	}
80	.label { display: block; margin-bottom: var(--space-2); font-size: var(--text-sm); line-height: var(--leading-tight); font-weight: var(--weight-medium); color: var(--color-muted); }
81	.input { display: block; width: 100%; height: var(--control-h); margin: 0; padding: 0 var(--space-3); font: inherit; font-size: var(--text-md); font-variant-numeric: tabular-nums;
82	  color: var(--color-text); background: var(--color-surface); border: var(--border-w) solid var(--color-field-border); border-radius: var(--radius-sm);
83	  transition: border-color var(--duration-fast) var(--ease-out), box-shadow var(--duration-fast) var(--ease-out); }
84	.input:hover, .input.is-hover { border-color: var(--color-field-border-hover); }
85	.input:focus { outline: none; }
86	.input:focus-visible, .input.is-focus { outline: var(--focus-w) solid var(--color-focus); outline-offset: var(--focus-offset); }
87	.input[aria-invalid="true"] { border-color: var(--color-error); box-shadow: inset 0 0 0 var(--border-w) var(--color-error); }
88	.input-wrap { position: relative; }
89	.input-wrap .input { padding-right: var(--space-8); }
90	.suffix { position: absolute; right: var(--space-3); top: 50%; transform: translateY(-50%); font-size: var(--text-base); line-height: var(--leading-none); color: var(--color-muted); pointer-events: none; }
91	.field-error { display: flex; align-items: flex-start; gap: var(--space-2); min-height: var(--error-slot-h); margin: var(--space-1) 0 var(--space-field-gap);
92	  font-size: var(--text-sm); line-height: var(--leading-tight); font-weight: var(--weight-medium); color: var(--color-error); }
93	.alert-icon { flex: none; width: var(--icon-sm); height: var(--icon-sm); margin-top: calc((var(--text-sm) * var(--leading-tight) - var(--icon-sm)) / 2); fill: var(--color-error); }
94	.alert-icon .alert-mark { fill: none; stroke: var(--color-surface); stroke-width: 1.8; stroke-linecap: round; }
95	.alert-icon .alert-dot { fill: var(--color-surface); }
96	
97	.rule { border: 0; border-top: var(--border-w) solid var(--color-border); margin: var(--space-2) 0 var(--space-5); }
98	
99	/* result area: reserved height so nothing below moves */
100	.result-body { margin-top: var(--space-2); min-height: var(--result-min-h); }
101	@container app (min-width: 600px) { .result-body { --result-min-h: 112px; } }
102	.result-msg { display: flex; align-items: flex-start; gap: var(--space-2); margin: 0; font-size: var(--text-base); line-height: var(--leading-normal); color: var(--color-muted); }
103	.result-msg .alert-icon { margin-top: calc((var(--text-base) * var(--leading-normal) - var(--icon-sm)) / 2); }
104	.outcome { display: grid; grid-template-columns: minmax(0, 1fr); grid-template-areas: "score" "verdict" "gap"; row-gap: var(--space-3); justify-items: start; }
105	@container app (min-width: 600px) {
106	  .outcome { grid-template-columns: auto minmax(0, 1fr); grid-template-areas: "score verdict" "gap gap"; column-gap: var(--space-6); align-items: center; }
107	}
108	.score { grid-area: score; margin: 0; font-size: var(--text-score); line-height: var(--leading-none); font-weight: var(--weight-light); letter-spacing: var(--tracking-score); font-variant-numeric: tabular-nums lining-nums; white-space: nowrap; }
109	.score .pct { font-size: 0.5em; letter-spacing: 0; color: var(--color-muted); margin-left: 0.04em; }
110	.verdict { grid-area: verdict; display: inline-flex; align-items: center; gap: var(--space-3); margin: 0; padding: var(--space-2) var(--space-5) var(--space-2) var(--space-2);
111	  border: var(--border-w) solid currentColor; border-radius: var(--radius-md);
112	  font-size: var(--text-verdict); line-height: var(--leading-none); font-weight: var(--weight-semibold); letter-spacing: var(--tracking-verdict); }
113	.verdict--pass { color: var(--color-pass); background: var(--color-pass-tint); }
114	.verdict--fail { color: var(--color-fail); background: var(--color-fail-tint); }
115	.verdict-disc { display: inline-grid; place-items: center; width: var(--icon-verdict); height: var(--icon-verdict); border-radius: 50%; background: currentColor; flex: none; }
116	.verdict-disc svg { width: 70%; height: 70%; }
117	.verdict-disc .i-stroke { fill: none; stroke: var(--color-surface); stroke-width: 3.2; stroke-linecap: round; stroke-linejoin: round; }
118	.verdict-msg { grid-area: verdict; margin: 0; font-size: var(--text-base); line-height: var(--leading-normal); color: var(--color-muted); }
119	.gap { grid-area: gap; display: flex; align-items: flex-start; gap: var(--space-2); margin: 0; font-size: var(--text-base); line-height: var(--leading-normal); font-variant-numeric: tabular-nums; color: var(--color-text); }
120	.gap-icon { flex: none; width: var(--icon-sm); height: var(--icon-sm); margin-top: calc((var(--text-base) * var(--leading-normal) - var(--icon-sm)) / 2); }
121	.gap-icon--pass { fill: var(--color-pass); }
122	.gap-icon--fail { fill: var(--color-fail); }
123	
124	.actions { display: flex; align-items: center; flex-wrap: wrap; gap: var(--space-3); margin-top: var(--space-6); }
125	.btn { min-height: var(--control-h); min-width: var(--control-h); padding: 0 var(--space-5); font: inherit; font-size: var(--text-base); font-weight: var(--weight-semibold);
126	  color: var(--color-accent); background: transparent; border: var(--border-w) solid var(--color-accent); border-radius: var(--radius-sm); cursor: pointer;
127	  transition: background-color var(--duration-fast) var(--ease-out), color var(--duration-fast) var(--ease-out); }
128	.btn:hover, .btn.is-hover { background: var(--color-accent-tint); }
129	.btn:focus { outline: none; }
130	.btn:focus-visible, .btn.is-focus { outline: var(--focus-w) solid var(--color-focus); outline-offset: var(--focus-offset); }
131	.btn:active, .btn.is-active { background: var(--color-accent); color: var(--color-surface); }
132	.hint { font-size: var(--text-sm); line-height: var(--leading-tight); color: var(--color-muted); }
133	kbd { font: inherit; font-size: var(--text-xs); padding: 0 var(--space-1); border: var(--border-w) solid var(--color-border); border-bottom-width: 2px; border-radius: var(--radius-sm); color: var(--color-muted); }
134	
135	@media (prefers-reduced-motion: reduce) { .input, .btn { transition: none; } }
136	
137	/* component-states panel (mockup only) */
138	.states-card { max-width: none; }
139	.demo-grid { display: grid; grid-template-columns: repeat(auto-fill, minmax(200px, 1fr)); column-gap: var(--space-6); }
140	.demo-row { display: flex; flex-wrap: wrap; gap: var(--space-6); margin: var(--space-2) 0 var(--space-6); }
141	.demo-cap { margin: 0 0 var(--space-1); font-size: var(--text-xs); line-height: var(--leading-tight); color: var(--color-muted); }
142	.demo .gap + .gap { margin-top: var(--space-1); }
143	</style>
144	</head>
145	<body>
146	<main class="page">
147	  <header class="page-head">
148	    <p class="kicker">Stage 4 · Quiz score and pass-mark calculator · Direction A "Ledger" + bigger verdict (DEC-10)</p>
149	    <h1>Design mockup: every result state, light and dark</h1>
150	    <p>Static picture of the spec in <code>ui-design.md</code>. Each frame stands in for a browser window; its card switches to the wide layout when the frame is at least 600px wide (the app uses the same 600px breakpoint on the viewport).</p>
151	    <p>Pass and Fail always show an icon and the word. Error messages always show an icon and text under the field. The result area keeps the same height in every state.</p>
152	  </header>
153	
154	  <section class="part" id="desktop">
155	    <h2 class="part-title">Desktop and tablet (window 600px and wider, card max 520px)</h2>
156	    <p class="part-note">States (a) to (e), light beside dark. Below 1000px of page width the pair stacks; below 600px each frame shows the mobile layout.</p>
157	    <div class="state" id="desktop-idle"><h3 class="state-title"><span class="state-letter">(a)</span> Idle / empty</h3><p class="state-note">Page just opened: marks earned and total empty, pass mark pre-filled &quot;70&quot; (M-1).</p><div class="pair"><div class="theme-cell"><p class="theme-label">Light</p><div class="theme theme--light viewport"><div class="app"><article class="card" aria-labelledby="title-1">
158	  <header class="card-head"><p class="eyebrow">Quiz score</p><h1 class="title" id="title-1">Check a quiz result</h1><p class="sub">A score at or above the pass mark is a pass.</p></header>
159	  <div class="fields">
160	    <div class="field field--earned"><label class="label" for="earned-3">Marks earned</label><input class="input" id="earned-3" type="text" inputmode="decimal" autocomplete="off" value="" aria-describedby="earned-3-error"><p class="field-error" id="earned-3-error"></p></div>
161	    <div class="field field--total"><label class="label" for="total-4">Total marks possible</label><input class="input" id="total-4" type="text" inputmode="decimal" autocomplete="off" value="" aria-describedby="total-4-error"><p class="field-error" id="total-4-error"></p></div>
162	    <div class="field field--passmark"><label class="label" for="passmark-5">Pass mark<span class="sr-only"> (percent)</span></label><div class="input-wrap"><input class="input" id="passmark-5" type="text" inputmode="decimal" autocomplete="off" value="70" aria-describedby="passmark-5-error"><span class="suffix" aria-hidden="true">%</span></div><p class="field-error" id="passmark-5-error"></p></div>
163	  </div>
164	  <hr class="rule">
165	  <section class="result" aria-labelledby="score-label-2">
166	    <p class="eyebrow" id="score-label-2">Score</p>
167	    <div class="result-body"><p class="result-msg"><span data-m="M-1">Enter marks earned and total marks possible to see the score.</span></p></div>
168	  </section>
169	  <div class="actions"><button class="btn" type="button" aria-keyshortcuts="Escape"><span data-m="M-25">Next learner</span></button><span class="hint">or press <kbd>Esc</kbd></span></div>
170	</article></div></div></div><div class="theme-cell"><p class="theme-label">Dark</p><div class="theme theme--dark viewport"><div class="app"><article class="card" aria-labelledby="title-6">
171	  <header class="card-head"><p class="eyebrow">Quiz score</p><h1 class="title" id="title-6">Check a quiz result</h1><p class="sub">A score at or above the pass mark is a pass.</p></header>
172	  <div class="fields">
173	    <div class="field field--earned"><label class="label" for="earned-8">Marks earned</label><input class="input" id="earned-8" type="text" inputmode="decimal" autocomplete="off" value="" aria-describedby="earned-8-error"><p class="field-error" id="earned-8-error"></p></div>
174	    <div class="field field--total"><label class="label" for="total-9">Total marks possible</label><input class="input" id="total-9" type="text" inputmode="decimal" autocomplete="off" value="" aria-describedby="total-9-error"><p class="field-error" id="total-9-error"></p></div>
175	    <div class="field field--passmark"><label class="label" for="passmark-10">Pass mark<span class="sr-only"> (percent)</span></label><div class="input-wrap"><input class="input" id="passmark-10" type="text" inputmode="decimal" autocomplete="off" value="70" aria-describedby="passmark-10-error"><span class="suffix" aria-hidden="true">%</span></div><p class="field-error" id="passmark-10-error"></p></div>
176	  </div>
177	  <hr class="rule">
178	  <section class="result" aria-labelledby="score-label-7">
179	    <p class="eyebrow" id="score-label-7">Score</p>
180	    <div class="result-body"><p class="result-msg"><span data-m="M-1">Enter marks earned and total marks possible to see the score.</span></p></div>
181	  </section>
182	  <div class="actions"><button class="btn" type="button" aria-keyshortcuts="Escape"><span data-m="M-25">Next learner</span></button><span class="hint">or press <kbd>Esc</kbd></span></div>
183	</article></div></div></div></div></div><div class="state" id="desktop-pass"><h3 class="state-title"><span class="state-letter">(b)</span> Pass result</h3><p class="state-note">17.5 of 23, pass mark 70 → 76.0%, Pass, M-8. Cursor in marks earned (focus ring).</p><div class="pair"><div class="theme-cell"><p class="theme-label">Light</p><div class="theme theme--light viewport"><div class="app"><article class="card" aria-labelledby="title-11">
