187	    <div class="field field--total"><label class="label" for="total-14">Total marks possible</label><input class="input" id="total-14" type="text" inputmode="decimal" autocomplete="off" value="23" aria-describedby="total-14-error"><p class="field-error" id="total-14-error"></p></div>
188	    <div class="field field--passmark"><label class="label" for="passmark-15">Pass mark<span class="sr-only"> (percent)</span></label><div class="input-wrap"><input class="input" id="passmark-15" type="text" inputmode="decimal" autocomplete="off" value="70" aria-describedby="passmark-15-error"><span class="suffix" aria-hidden="true">%</span></div><p class="field-error" id="passmark-15-error"></p></div>
189	  </div>
190	  <hr class="rule">
191	  <section class="result" aria-labelledby="score-label-12">
192	    <p class="eyebrow" id="score-label-12">Score</p>
193	    <div class="result-body"><div class="outcome"><p class="score">76.0<span class="pct">%</span></p><p class="verdict verdict--pass"><span class="verdict-disc"><svg viewBox="0 0 24 24" aria-hidden="true" focusable="false"><path class="i-stroke" d="M6.5 12.5l3.8 3.8 7.4-8.3"/></svg></span><span data-m="M-4">Pass</span></p><p class="gap"><svg class="gap-icon gap-icon--pass" viewBox="0 0 16 16" aria-hidden="true" focusable="false"><path d="M8 3.5l5 7H3z"/></svg><span data-m="M-8">1.4 marks above the pass mark</span></p></div></div>
194	  </section>
195	  <div class="actions"><button class="btn" type="button" aria-keyshortcuts="Escape"><span data-m="M-25">Next learner</span></button><span class="hint">or press <kbd>Esc</kbd></span></div>
196	</article></div></div></div><div class="theme-cell"><p class="theme-label">Dark</p><div class="theme theme--dark viewport"><div class="app"><article class="card" aria-labelledby="title-16">
197	  <header class="card-head"><p class="eyebrow">Quiz score</p><h1 class="title" id="title-16">Check a quiz result</h1><p class="sub">A score at or above the pass mark is a pass.</p></header>
198	  <div class="fields">
